import AppKit
import Darwin
import HexpadKit

/// Debug Info / Command Line Arguments dialogs for the Help menu (H25a).
///
/// The dialogs are presented as modal `NSAlert`s with a read-only, selectable
/// text view in the accessory view and a Copy button that puts the whole report
/// on the pasteboard. The report itself is generated by the pure, testable
/// ``debugReport(activeController:)`` function so tests can assert its contents
/// without spinning up AppKit UI.
final class DebugInfoWindowController {

    // MARK: - Debug Info report

    /// Builds the full Debug Info report from live runtime data.
    ///
    /// `activeController` may be `nil` (no window / headless host); every
    /// session field then degrades to a safe empty value rather than crashing.
    static func debugReport(activeController: MainWindowController?) -> String {
        let bundle = Bundle.main
        let appName = (bundle.object(forInfoDictionaryKey: "CFBundleName") as? String)
            .flatMap { $0.isEmpty ? nil : $0 } ?? "Hexpad"
        let version = (bundle.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String)
            .flatMap { $0.isEmpty ? nil : $0 } ?? "unknown"
        let build = (bundle.object(forInfoDictionaryKey: "CFBundleVersion") as? String)
            .flatMap { $0.isEmpty ? nil : $0 } ?? "unknown"
        let bundleID = bundle.bundleIdentifier ?? "unknown"

        let process = ProcessInfo.processInfo
        let preferences = PreferencesStore.load()

        var lines: [String] = []

        lines.append("App")
        lines.append("Name: \(appName)")
        lines.append("Version: \(version)")
        lines.append("Build: \(build)")
        lines.append("Bundle Identifier: \(bundleID)")
        lines.append("")

        lines.append("System")
        lines.append("macOS: \(process.operatingSystemVersionString)")
        lines.append("Host: \(process.hostName)")
        lines.append("Model: \(hostModel())")
        lines.append("CPU count: \(process.processorCount)")
        lines.append("Physical memory: \(ByteCountFormatter.string(fromByteCount: Int64(process.physicalMemory), countStyle: .memory))")
        lines.append("")

        lines.append("Session")
        if let controller = activeController {
            for pane in controller.allPanes {
                let label = pane.group == .primary ? "Group 1 (primary)" : "Group 2 (secondary)"
                lines.append("\(label): \(pane.tabStore.count) tab(s)")
            }
            lines.append("Focused group: \(controller.focusedGroup == .primary ? "primary" : "secondary")")
            if let doc = controller.tabStore.selectedDocument {
                lines.append("Active document: \(doc.name)")
                lines.append("Path: \(doc.filePath?.path ?? "(untitled)")")
            } else {
                lines.append("Active document: (none)")
                lines.append("Path: (none)")
            }
            let unsaved = controller.allPanes.flatMap { $0.tabStore.documents }.filter { $0.unsavedChanges }.count
            lines.append("Unsaved documents: \(unsaved)")
        } else {
            lines.append("Open tabs: 0")
            lines.append("Focused group: (none)")
            lines.append("Active document: (none)")
            lines.append("Path: (none)")
            lines.append("Unsaved documents: 0")
        }
        lines.append("")

        lines.append("Configuration")
        lines.append("Theme: \(preferences.theme)")
        lines.append("Font family: \(preferences.fontFamily)")
        lines.append("Font size: \(preferences.fontSize)")
        lines.append("Word wrap: \(preferences.wordWrap)")
        lines.append("Tab size: \(preferences.tabSize)")
        lines.append("Use tabs: \(preferences.useTabs)")
        lines.append("Minimap visible: \(preferences.minimapVisible)")
        lines.append("Show tab bar: \(preferences.showTabBar)")
        lines.append("Lock tab bar: \(preferences.lockTabBar)")
        lines.append("Double-click tab closes: \(preferences.doubleClickTabCloses)")
        lines.append("Max tab label length: \(preferences.maxTabLabelLength)")
        lines.append("Close button visibility: \(preferences.closeButtonVisibility)")
        lines.append("Session snapshot enabled: \(preferences.sessionSnapshotEnabled)")
        lines.append("")

        lines.append("Server/Runtime")
        lines.append("Process name: \(process.processName)")
        lines.append("Process ID: \(process.processIdentifier)")

        return lines.joined(separator: "\n")
    }

    // MARK: - Command Line Arguments text

    static func commandLineArgumentsText() -> String {
        """
        Command Line Arguments

        Hexpad opens files handed to it by Launch Services. It defines no
        command-line flags of its own.

        Supported usage:
          open -a Hexpad file.txt
          open -a Hexpad file1.txt file2.md

        Each argument is treated as a file path or URL and opened in its own tab.
        If Hexpad is not already running, a window is created for the files.

        Files can also be opened with File > Open, by dragging onto the Dock
        icon, or by double-clicking in Finder.
        """
    }

    // Aliases for callers that use a different name.
    static func commandLineArguments() -> String { commandLineArgumentsText() }
    static func commandLineArgumentsReport() -> String { commandLineArgumentsText() }
    static func cliArgumentsText() -> String { commandLineArgumentsText() }
    static func debugInfoReport(activeController: MainWindowController?) -> String {
        debugReport(activeController: activeController)
    }

    // MARK: - Runtime helpers

    static func hostModel() -> String {
        var size = 0
        sysctlbyname("hw.model", nil, &size, nil, 0)
        guard size > 0 else { return "Unknown" }
        var buffer = [CChar](repeating: 0, count: size)
        guard sysctlbyname("hw.model", &buffer, &size, nil, 0) == 0 else { return "Unknown" }
        return String(cString: buffer)
    }

    // MARK: - Dialogs

    static func showDebugInfo(activeController: MainWindowController?) {
        let report = debugReport(activeController: activeController)
        presentCopyableAlert(title: "Debug Info", text: report)
    }

    static func showCommandLineArguments() {
        presentCopyableAlert(title: "Command Line Arguments", text: commandLineArgumentsText())
    }

    private static func presentCopyableAlert(title: String, text: String) {
        let alert = NSAlert()
        alert.messageText = title
        alert.informativeText = "Copy this text into a bug report or terminal invocation."
        alert.alertStyle = .informational

        let scrollView = NSScrollView(frame: NSRect(x: 0, y: 0, width: 520, height: 300))
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = true
        scrollView.borderType = .bezelBorder

        let textView = NSTextView(frame: scrollView.bounds)
        textView.autoresizingMask = [.width, .height]
        textView.isEditable = false
        textView.isSelectable = true
        textView.font = NSFont.monospacedSystemFont(ofSize: 11, weight: .regular)
        textView.string = text
        scrollView.documentView = textView

        alert.accessoryView = scrollView

        alert.addButton(withTitle: "Copy")
        alert.addButton(withTitle: "Close")

        let response = alert.runModal()
        if response == .alertFirstButtonReturn {
            let pasteboard = NSPasteboard.general
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
        }
    }
}
